//Implementa comparable
public abstract class Integracion implements Comparable<Integracion> {
    protected String id;
    protected String nombre;
    protected int latencia;
    protected boolean listo;
    protected String configuracion;

    public Integracion() {
        id = "";
        nombre = "";
        latencia = 0;
        listo = false;
        configuracion = "";
    }

    public Integracion(String id, String nombre, int latencia, boolean listo, String configuracion) {
        this.id = id;
        this.nombre = nombre;
        this.latencia = latencia;
        this.listo = listo;
        this.configuracion = configuracion;
    }


    // Setters y getters

    public void setId(String newId) {
        id = newId;
    }

    public String getId() {
        return id;
    }


    public void setNombre(String newNombre) {
        nombre = newNombre;
    }

    public String getNombre() {
        return nombre;
    }


    public void setLatencia(int newLatencia) {
        latencia = newLatencia;
    }

    public int getLatencia() {
        return latencia;
    }


    public void setListo(boolean newListo) {
        listo = newListo;
    }

    public boolean getListo() {
        return listo;
    }


    public void setConfiguracion(String newConfiguracion) {
        configuracion = newConfiguracion;
    }

    public String getConfiguracion() {
        return configuracion;
    }


    // Un nuevo comparable (override)
    //
    //
    // Devuelve:
    // Un numero negativo si esta integracion va primero.
    // Cero si tienen la misma latencia y el mismo ID.
    @Override
    public int compareTo(Integracion otra) {

        // Compara las latencias
        if (latencia < otra.getLatencia()) {
            return -1;
        }
        else if (latencia > otra.getLatencia()) {
            return 1;
        }
        else {
            // Si las latencias son iguales, usar ID
			//Esto ya lo compara Java asi no más, alfabéticamente, según averigué
            return id.compareTo(otra.getId());
        }
    }

    // Sobreescribir el toString

    @Override
    public String toString() {
		//Segun listo (a.k.a, el boolean)
        String estado;
        if (listo) {
            estado = "Conectado";
        }
        else {
            estado = "Desconectado";
        }
        return "ID: " + id
            + "\nNombre: " + nombre
            + "\nLatencia: " + latencia + " ms"
            + "\nEstado: " + estado
            + "\nConfiguracion: " + configuracion;
    }
}
